//! English words whose Telex keystrokes would otherwise form valid Vietnamese
//! (`these` → `thế`, `car` → `cả`). Generated by `tools/gen-dict`, then reviewed.

use std::sync::OnceLock;

const LIST: &str = include_str!("english.txt");

fn words() -> &'static [&'static str] {
    static WORDS: OnceLock<Vec<&'static str>> = OnceLock::new();
    WORDS.get_or_init(|| {
        let mut words: Vec<&str> = LIST
            .lines()
            .map(str::trim)
            .filter(|l| !l.is_empty() && !l.starts_with('#'))
            .collect();
        words.sort_unstable();
        words.dedup();
        words
    })
}

/// `word` must already be ASCII-lowercased.
pub(crate) fn contains(word: &str) -> bool {
    words().binary_search(&word).is_ok()
}

#[cfg(test)]
mod tests {
    #[test]
    fn list_is_clean() {
        for w in super::words() {
            assert!(
                !w.is_empty()
                    && w.len() <= crate::MAX_KEYS
                    && w.bytes().all(|b| b.is_ascii_lowercase()),
                "bad entry in english.txt: {w:?}"
            );
        }
    }
}
